    function resolveTab(tabId){return TAB_ALIASES[tabId]||tabId;}
    function activate(tabId){
      const fallback=buttons[0]?.dataset.editorTab;
      const requested=resolveTab(tabId);
      const next=Array.from(panels).some((panel)=>panel.id===requested)?requested:fallback;
      if(!next)return;
      buttons.forEach((button)=>{const active=button.dataset.editorTab===next;button.classList.toggle('active',active);button.setAttribute('aria-selected',active?'true':'false');});
      panels.forEach((panel)=>{const active=panel.id===next;panel.hidden=!active;panel.classList.toggle('active',active);});
      try{history.replaceState(null,'',`#${next}`);}catch{}
    }
    buttons.forEach((button)=>button.addEventListener('click',()=>activate(button.dataset.editorTab)));
    const initialHash=location.hash?.replace('#','');
    const requested=initialHash?resolveTab(initialHash):'';
    const initial=requested&&document.getElementById(requested)?requested:buttons[0]?.dataset.editorTab;
    if(initial)activate(initial);
