  async function saveCombined(event){event?.preventDefault?.();const status=document.getElementById('profile-edit-message');const saveButtons=document.querySelectorAll('button[form="profile-edit-form"], #profile-edit-form button[type="submit"]');if(!profileLoaded){status.textContent='Profile has not loaded yet. Please wait before saving.';return;}const pendingCardBody=cardSaveBody();saveButtons.forEach((btn)=>btn.disabled=true);status.textContent='Saving...';let profileOk=false;let cardOk=false;const errors=[];try{const d=await fetchJsonSafe('/api/profile/me',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(profileSaveBody())});profileOk=true;if(d?.profile)applyProfileToForm({...d.profile,...pendingCardBody,cardTileSettings:pendingCardBody.cardTileSettings});if(d?.achievementsAwarded?.length)showAchievementToast(d.achievementsAwarded);}catch(error){errors.push(`Profile save failed: ${error?.message||'Unknown error'}`);}try{const d=await fetchJsonSafe('/api/profile/me/card',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(pendingCardBody)});cardOk=true;if(d?.profile)applyProfileToForm(d.profile);if(d?.achievementsAwarded?.length)showAchievementToast(d.achievementsAwarded);}catch(error){errors.push(`Profile Card save failed: ${error?.message||'Unknown error'}`);}if(profileOk&&cardOk){formDirty=false;status.textContent='Profile and Profile Card saved.';}else if(profileOk||cardOk){status.textContent=`${profileOk?'Profile saved':'Profile save failed'}, but ${cardOk?'Profile Card saved':'Profile Card save failed'}: ${errors.join(' ')}`;}else{status.textContent=errors.join(' ')||'Save failed.';}renderPreview();saveButtons.forEach((btn)=>btn.disabled=false);}
  function showAchievementToast(items){try{const panel=document.createElement('div');panel.className='achievement-toast';panel.innerHTML=`<strong>Achievement unlocked</strong><ul class="achievement-unlocked-list">${items.map((a)=>`<li>${escAttr(a.title||a.achievement_key)} +${Number(a.xp_awarded||a.xp?.amount||0)} XP</li>`).join('')}</ul>`;document.body.append(panel);setTimeout(()=>panel.remove(),7000);}catch{}}
  async function load(){const status=document.getElementById('profile-edit-message');try{const cached=window.GREVApi?.readSessionCache?.('grev_api_cache:/api/profile/me');if(cached?.data?.profile&&!formDirty){applyProfileToForm(cached.data.profile);status.textContent='Loaded cached profile.';}let d;try{d=await fetchJsonSafe('/api/bootstrap/edit-profile');}catch(error){d=await fetchJsonSafe('/api/profile/me');}if(!formDirty)applyProfileToForm(d.profile||{});profileLoaded=true;document.querySelectorAll('button[form="profile-edit-form"], #profile-edit-form button[type="submit"]').forEach((btn)=>{btn.disabled=false;});status.textContent='Loaded.';loadLeetifyPreviewData();loadExternalConnections();}catch(error){console.error('[profile-editor] load failed',error);status.textContent=`Load failed: ${error?.message||'Unknown error'}`;document.querySelectorAll('button[form="profile-edit-form"], #profile-edit-form button[type="submit"]').forEach((btn)=>{btn.disabled=true;});}}
  function bindEvents(){const form=document.getElementById('profile-edit-form');form.addEventListener('submit',saveCombined);document.getElementById('save-cs2-connection')?.addEventListener('click',saveCs2Connection);document.getElementById('disconnect-cs2')?.addEventListener('click',disconnectCs2Connection);document.getElementById('sync-cs2-stats')?.addEventListener('click',syncCs2Stats);document.getElementById('save-faceit-connection')?.addEventListener('click',saveFaceitConnection);document.getElementById('disconnect-faceit')?.addEventListener('click',disconnectFaceitConnection);document.getElementById('sync-faceit-stats')?.addEventListener('click',syncFaceitStats);document.getElementById('reset-profile-page-layout')?.addEventListener('click',()=>{hiddenState.profile_page_tile_layout_json='';document.getElementById('profile-edit-message').textContent='Profile layout will reset on save. Widget styles are unchanged.';formDirty=true;});document.querySelector('[name="profile_page_overlay_strength"]')?.addEventListener('input',updateOverlayLabel);form.addEventListener('input',(e)=>{formDirty=true;if(e.target?.name){editorProfile=collectFormProfile();window.editorProfile=editorProfile;updateImagePreview(e.target);}if(['website_url','steam_url','leetify_profile_url','refrag_profile_url','spotify_url','soundcloud_url','youtube_music_url'].includes(e.target?.name)){collectLinkVisibility();renderLinksVisibilityControls(collectFormProfile());if(e.target.name==='steam_url')updateCs2SteamUrlSource();}renderPreview();});form.addEventListener('change',()=>{formDirty=true;editorProfile=collectFormProfile();window.editorProfile=editorProfile;renderPreview();});document.body.addEventListener('input',(e)=>{if(e.target.dataset.cardTileVisible||e.target.name&&CARD_TOGGLES.includes(e.target.name)){const n=e.target.name;if(n&&CARD_TOGGLES.includes(n)){editorProfile[n]=e.target.checked?1:0;renderTileEditors();renderPreview();return;}}if(e.target.id==='card_grid_columns'){editorProfile.card_grid_columns=safeCols(e.target.value);renderPreview();return;}if(e.target.id==='card_layout'){editorProfile.card_layout=e.target.value;renderPreview();return;}if(e.target.dataset.settingsTileEnable){const key=e.target.dataset.settingsTileEnable;editorProfile.cardTileSettings[key]=editorProfile.cardTileSettings[key]||{...CARD_DEFAULTS[key]};editorProfile.cardTileSettings[key].enabled=e.target.checked;renderTileEditors();renderPreview();return;}if(e.target.dataset.linkTileEnable){const key=e.target.dataset.linkTileEnable;editorProfile.cardTileSettings[key]=editorProfile.cardTileSettings[key]||{...CARD_DEFAULTS[key]};editorProfile.cardTileSettings[key].enabled=e.target.checked;renderTileEditors();renderPreview();return;}if(e.target.dataset.linkTile&&e.target.dataset.linkKey){const key=e.target.dataset.linkTile;editorProfile.cardTileSettings[key]=editorProfile.cardTileSettings[key]||{...CARD_DEFAULTS[key]};const current=new Set(Array.isArray(editorProfile.cardTileSettings[key].linkKeys)?editorProfile.cardTileSettings[key].linkKeys:[]);if(e.target.checked)current.add(e.target.dataset.linkKey);else current.delete(e.target.dataset.linkKey);editorProfile.cardTileSettings[key].linkKeys=LINK_SERVICE_KEYS.filter((linkKey)=>current.has(linkKey));renderPreview();return;}if(e.target.dataset.k){const key=e.target.dataset.k;const prop=e.target.dataset.p;editorProfile.cardTileSettings[key]=editorProfile.cardTileSettings[key]||{...CARD_DEFAULTS[key]};if(prop==='colour'){editorProfile.cardTileSettings[key][prop]=e.target.value;e.target.dataset.empty='0';}else if(prop==='maxIcons')editorProfile.cardTileSettings[key][prop]=Math.max(1,Math.min(8,Number(e.target.value)||8));else editorProfile.cardTileSettings[key][prop]=e.target.value;renderPreview();return;}if(CARD_APPEARANCE_FIELDS.includes(e.target.id)){if(e.target.type==='color'){const isEmpty=e.target.dataset.empty==='1';editorProfile[e.target.id]=isEmpty?'':e.target.value;}else editorProfile[e.target.id]=e.target.value.trim();renderPreview();}});document.body.addEventListener('change',(e)=>{if(e.target.dataset.previewSizeTile){setPreviewTileSpan(e.target.dataset.previewSizeTile,e.target.value);return;}if(CARD_APPEARANCE_FIELDS.includes(e.target.id)&&e.target.type==='color'){e.target.dataset.empty='0';editorProfile[e.target.id]=e.target.value;renderPreview();}});document.body.addEventListener('click',(e)=>{const previewMoveButton=e.target.closest('[data-preview-move][data-preview-tile-key]');if(previewMoveButton){e.preventDefault();e.stopPropagation();movePreviewTile(previewMoveButton.dataset.previewTileKey,previewMoveButton.dataset.previewMove);return;}const hideButton=e.target.closest('[data-hide-preview-tile]');if(hideButton){e.preventDefault();e.stopPropagation();hideProfileCardPreviewTile(hideButton.dataset.hidePreviewTile);return;}const clearField=e.target.dataset.clear;if(clearField&&CARD_APPEARANCE_FIELDS.includes(clearField)){editorProfile[clearField]='';const el=document.getElementById(clearField);if(el){el.value='';el.dispatchEvent(new Event('input',{bubbles:true}));}syncCardAppearanceInputs();renderPreview();return;}const clearColour=e.target.dataset.clearColour;if(clearColour){editorProfile.cardTileSettings[clearColour].colour='';renderTileEditors();renderPreview();return;}const dir=e.target.dataset.move;const moveKey=e.target.dataset.key;if(dir&&moveKey){const keys=getOrderedTileKeys(editorProfile.cardTileSettings);const idx=keys.indexOf(moveKey);const target=dir==='up'?idx-1:idx+1;if(target>=0&&target<keys.length){[keys[idx],keys[target]]=[keys[target],keys[idx]];keys.forEach((key,i)=>{editorProfile.cardTileSettings[key]=editorProfile.cardTileSettings[key]||{};editorProfile.cardTileSettings[key].order=(i+1)*10;});renderTileEditors();renderPreview();}}});document.getElementById('check-leetify')?.addEventListener('click',async()=>{const status=document.getElementById('leetify-check-status');try{status.textContent='Saving profile before checking Leetify...';const d=await fetchJsonSafe('/api/profile/me',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(profileSaveBody())});if(d?.profile)applyProfileToForm(d.profile);status.textContent='Checking Leetify Public API...';const data=await fetchJsonSafe('/api/integrations/leetify/profile?user_id='+encodeURIComponent(d.profile?.id||editorProfile.id||''));editorProfile.leetifyData=data;renderPreview();status.textContent=data.available?`Leetify data available. ${data.nickname||data.name||'Profile found'} · Data Provided by Leetify`:(data.reason||'Leetify Public API data unavailable for this profile.');}catch(error){status.textContent=`Leetify check failed: ${error?.message||'Unknown error'}`;}});}
